package com.mockarena.assessment.domain; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="attempt_results",schema="assessment") public class AttemptResult{@Id private UUID attemptId;@Enumerated(EnumType.STRING)@Column(nullable=false)private EvaluationStatus evaluationStatus;private BigDecimal rawScore,maxScore,percentage;private Instant evaluatedAt,releasedAt;@Version private long version;@Column(nullable=false)private Instant createdAt,updatedAt;protected AttemptResult(){}public AttemptResult(UUID id,EvaluationStatus s,BigDecimal score,BigDecimal max,BigDecimal pct,Instant now,Instant release){attemptId=id;evaluationStatus=s;rawScore=score;maxScore=max;percentage=pct;evaluatedAt=now;releasedAt=release;createdAt=now;updatedAt=now;}public UUID attemptId(){return attemptId;}public EvaluationStatus evaluationStatus(){return evaluationStatus;}public BigDecimal rawScore(){return rawScore;}public BigDecimal maxScore(){return maxScore;}public BigDecimal percentage(){return percentage;}public Instant evaluatedAt(){return evaluatedAt;}public Instant releasedAt(){return releasedAt;}}
